multiset<int> lo, hi;                 // lo: max-half, hi: min-half
auto rebalance = [&]{
    while ((int)lo.size() - (int)hi.size() > 1)
        hi.insert(prev(lo.end()) == lo.end() ? 0 : *prev(lo.end())), // move max of lo
        lo.erase(prev(lo.end()));
    while (lo.size() < hi.size())
        lo.insert(*hi.begin()), hi.erase(hi.begin());
};
